// ── CONFIG ── set once (stored encrypted).
const OPENAI_API_KEY = 'PASTE_OPENAI_API_KEY';
const MODEL = 'gpt-4o-mini'; // supports vision

const src = $json.body || $json;
const imageUrl = src.image_url;
if (!imageUrl) return { json: { text: '' } };

try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
    body: {
      model: MODEL,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: 'Extract ALL visible text from this image verbatim. If there is no text, reply with an empty string. Return only the extracted text.' },
          { type: 'image_url', image_url: { url: imageUrl } }
        ]
      }],
      max_tokens: 1024
    },
    json: true
  });
  const text = res?.choices?.[0]?.message?.content ?? '';
  return { json: { text } };
} catch (e) {
  return { json: { text: '', error: String((e && e.message) || e) } };
}
